def score(program: str) -> float:
    import ast

    # Check syntax validity
    try:
        tree = ast.parse(program)
    except:
        return 0.0

    # Verify it has the required score function
    if not any(isinstance(n, ast.FunctionDef) and n.name == 'score' for n in ast.walk(tree)):
        return 0.0

    # Count AST nodes
    node_count = len(list(ast.walk(tree)))

    # Enforce size limit strictly
    if node_count > 100:
        return 0.0

    # Score inversely with size: simpler code scores higher
    return 1.0 - (node_count / 100.0)

